    """Every citation token must keep riding on the evidence it supports.

    A count-only check passes a rewrite that moves [Smith2020] into another
    clause, which changes what the citation is claimed to support. Binding is
    judged relative to the quotation, not to sentence identity: a legitimate
    rewrite may change the words around a protected quote.
    """
    problems: list[str] = []
    relation = re.compile(r"[^\s\u201c\u201d\"\u300c\u300d]{1,200}\s*" + BRACKET_CITATION.pattern)

    def payloads(text: str) -> list[str]:
        out: list[str] = []
        for groups in QUOTED.findall(text):
            for quote in groups:
                if not quote:
                    continue
                end = text.find(quote) + len(quote)
                tail = text[end:end + 200]
                if relation.match(tail):
                    out.append(quote + "|" + BRACKET_CITATION.search(tail).group(0))
        return out

    after_payloads = payloads(after_text)
    for payload in payloads(before_text):
        if payload not in after_payloads:
            problems.append(
                f"[{label}] citation no longer rides on its quotation: {payload!r}"
            )
    for payload in after_payloads:
        if payload not in payloads(before_text):
            problems.append(
                f"[{label}] citation attached to a quotation that did not carry it: {payload!r}"
            )
    return problems


